const colors=['#e57f75','#9b3e3a','#ef9b45','#b5672f','#e2bf54','#95752a','#82b978','#2f6b4f','#76c8c8','#287878','#83afe2','#305c9b','#b595da','#6c468f','#ed9bc2','#9b496d','#8b6d55','#6e7479','#171717','#f4f1e8'];

const qs=new URL(location.href).searchParams;
const session={roomId:qs.get('room'),playerToken:null,hostToken:null,state:null,preview:null,events:null,name:localStorage.getItem('gn_name')||'',selectedCard:null,selectedBid:null,error:null,ceremonyDismissed:false,scheduleOpen:false,connectionIssue:false,connectTimer:null};
const voice={enabled:false,muted:false,stream:null,peers:new Map(),connected:new Set(),error:null};
function tokenKey(kind,room=session.roomId){return room?`gn_${kind}_${room}`:`gn_${kind}`}
if(session.roomId){session.playerToken=localStorage.getItem(tokenKey('player'));session.hostToken=localStorage.getItem(tokenKey('host'))}

function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function pastGames(){try{return JSON.parse(localStorage.getItem('gn_game_history')||'[]')}catch{return[]}}
function saveGameSummary(s){if(!s||s.game?.phase!=='gameOver')return;const games=pastGames();if(games.some(g=>g.roomId===s.id&&g.rounds===s.game.history.length))return;const winners=s.game.winnerIds.map(id=>s.players.find(p=>p.id===id)?.name).filter(Boolean);games.unshift({roomId:s.id,at:Date.now(),game:s.gameName,rounds:s.game.history.length,winners,players:s.players.map(p=>({name:p.name,score:p.score,avatar:p.avatar}))});localStorage.setItem('gn_game_history',JSON.stringify(games.slice(0,50)))}
async function api(path,body={}){const r=await fetch(`/api/${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Request failed');return data}
async function fetchState(room,token=''){const r=await fetch(`/api/state?room=${encodeURIComponent(room)}&token=${encodeURIComponent(token)}`,{cache:'no-store'});if(!r.ok)throw new Error('Room not found');return r.json()}
function setError(e){session.error=e?.message||String(e);render();setTimeout(()=>{session.error=null;render()},3600)}
function inviteLink(){return `${location.origin}/?room=${session.roomId}`}
function topbar(){return `<div class="topbar"><div class="brand"><div class="brand-mark">🂡</div><div>Black Family Game Night <span class="app-version">v${APP_VERSION}</span></div></div></div>`}
function shell(inner){return `<div class="shell">${topbar()}${session.error?`<div class="page"><div class="error">${esc(session.error)}</div></div>`:''}${inner}</div>`}

function avatarImagePath(p){const a=avatarByKey[p?.avatar]||avatars[0],style=avatarStyles[(Number(p?.variant)||0)%avatarStyles.length][0];return `/avatars/styles/${a[0]}-${style}.jpg`}
function avatarHTML(p,cls='avatar'){const a=avatarByKey[p?.avatar]||avatars[0],color=p?.color||'#2f6b4f',outfit=outfitColors[(Number(p?.outfitVariant)||0)%outfitColors.length],style=avatarStyles[(Number(p?.variant)||0)%avatarStyles.length];return `<div class="${cls} avatar-frame style-${style[0]}" style="--pc:${color};--outfit:${outfit}" title="${esc(a[1])} · ${style[1]}"><img src="${avatarImagePath(p)}" alt="${esc(a[1])}, ${style[1]}"><span class="outfit-tint"></span><span class="avatar-style-mark">${style[2]}</span></div>`}
function home(){
 const recent=pastGames().slice(0,4);
 const live=Object.entries(gameMeta).map(([key,m])=>`<article class="game-card playable"><div class="game-icon">${m.icon}</div><span class="tag live">PLAY NOW</span><h3>${esc(m.name)}</h3><p class="muted small">${esc(m.sub)}</p><button class="btn primary full" data-create-game="${key}">Create Game</button></article>`).join('');
 const future='';
 const recentHtml=recent.length?`<section style="margin-top:24px"><h2 style="font-family:Georgia,serif">Past games on this device</h2><div class="recent-games">${recent.map(g=>`<div class="panel"><strong>${esc(g.game)}</strong><div class="small muted">${new Date(g.at).toLocaleDateString()} · ${g.rounds} rounds</div><div style="margin-top:6px">🏆 ${esc(g.winners.join(' & ')||'Tie')}</div><div class="small muted">${g.players.map(p=>`${esc(p.name)} ${p.score}`).join(' · ')}</div></div>`).join('')}</div></section>`:'';
 return shell(`<main class="page"><section class="hero"><div class="hero-kicker">Built for John Black</div><div class="john-hero"><img src="/avatars/john-black.png" alt="Illustrated portrait of John Black"><div><strong>John Black</strong><span>Host · Birthday Guy</span></div></div><h1>Black Family <span>Game Night</span></h1><p><strong>Welcome to the Black Family Lodge.</strong> Eighteen games, one family table, and a birthday gift built for plenty of good-natured scorekeeping arguments.</p><div class="birthday-dedication">Happy Birthday, John! <span>Let the good times roll.</span></div></section><div class="game-grid">${live}${future}</div>${recentHtml}</main>`)
}
function joinScreen(){const name=session.preview?.gameName||'Game Night';return shell(`<main class="page"><div class="panel" style="max-width:720px;margin:32px auto"><h1 style="font-family:Georgia,serif;margin-top:0">Join ${esc(name)}</h1><p class="muted">Enter your name. In the lobby you can choose your detailed avatar, colour and seat.</p><div class="field"><label>Your name</label><input id="joinName" maxlength="24" value="${esc(session.name)}" placeholder="Pat"></div><div style="height:12px"></div><button class="btn primary full" data-action="join">Join Room</button></div></main>`)}

function tablePositions(n){if(n===1)return[{left:50,top:88}];const out=[];for(let i=0;i<n;i++){const a=Math.PI/2-(i*2*Math.PI/n);out.push({left:50+42*Math.cos(a),top:50+39*Math.sin(a)})}return out}
function rotatePlayers(players,meId){const sorted=[...players].sort((a,b)=>a.seat-b.seat);const idx=sorted.findIndex(p=>p.id===meId);return idx<0?sorted:[...sorted.slice(idx),...sorted.slice(0,idx)]}
function occupiedSeat(roomState,seat,meId){return roomState.players.some(p=>p.id!==meId&&p.seat===seat)}
function avatarPicker(me){const selected=avatarByKey[me.avatar]||avatars[0],style=avatarStyles[(Number(me.variant)||0)%avatarStyles.length];return `<div class="panel avatar-panel"><div class="avatar-customizer"><div class="avatar-preview">${avatarHTML(me,'preview-avatar')}<div><strong>${esc(selected[1])}</strong><div class="small muted">${style[1]} style · choose an outfit accent and player colour</div></div></div><div><strong>1. Choose your character</strong><div class="small muted">20 character families plus John’s special Birthday Guy avatar. Duplicates are welcome.</div><div class="avatar-grid" style="margin-top:10px">${avatars.map(([id,label])=>`<button class="avatar-choice ${me.avatar===id?'selected':''}" data-avatar="${id}" title="${esc(label)}"><img src="/avatars/styles/${id}-${style[0]}.jpg" alt="${esc(label)}"></button>`).join('')}</div></div><div class="style-section"><strong>2. Pick a style</strong><div class="avatar-style-grid">${avatarStyles.map((s,i)=>`<button class="style-choice ${Number(me.variant||0)===i?'selected':''}" data-style="${i}"><span>${s[2]}</span>${s[1]}</button>`).join('')}</div></div><div class="style-section"><strong>3. Pick an outfit colour</strong><div class="small muted">This changes the clothing accent, separate from your player identity colour.</div><div class="outfit-swatches">${outfitColors.map((c,i)=>`<button class="outfit-swatch ${Number(me.outfitVariant||0)===i?'selected':''}" style="background:${c}" data-outfit="${i}" title="Outfit colour ${i+1}"></button>`).join('')}</div></div><div class="style-section"><strong>4. Pick your player colour</strong><div class="small muted">Your ring, board pieces and identity colour throughout Game Night.</div><div class="swatches" style="margin-top:10px">${colors.map(c=>`<button class="swatch ${me.color===c?'selected':''}" style="background:${c}" data-color="${c}"></button>`).join('')}</div></div></div></div>`}
function voiceSupported(){return !!(navigator.mediaDevices?.getUserMedia&&window.RTCPeerConnection)}
function voiceIsSecure(){return location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'}
function voiceStatusText(s){if(!voiceSupported())return'Not supported by this browser';if(!voiceIsSecure())return'Available after the app is hosted securely';if(!voice.enabled)return'Optional · microphone stays off until you join';return `${voice.muted?'Muted':'Mic on'} · ${voice.connected.size+1}/${Math.min(s.players.length,8)} in voice`}
function voicePanel(s){const tooMany=s.players.length>8;return `<div class="panel voice-panel"><div class="spread"><div><strong>Voice chat</strong><div class="small muted">${esc(voiceStatusText(s))}</div></div><span class="voice-dot ${voice.enabled?'on':''}"></span></div>${tooMany?`<p class="small muted">Voice chat supports up to 8 people in a room. The card game can still have more players.</p>`:''}<div class="row wrap" style="margin-top:10px"><button class="btn ${voice.enabled?'cream':'good'}" data-action="voiceToggle" ${(!voiceSupported()||!voiceIsSecure()||tooMany)?'disabled':''}>${voice.enabled?'Leave Voice':'Join Voice'}</button>${voice.enabled?`<button class="btn ${voice.muted?'gold':'cream'}" data-action="voiceMute">${voice.muted?'Unmute':'Mute Mic'}</button>`:''}</div>${voice.error?`<div class="small" style="color:#9d3932;margin-top:8px">${esc(voice.error)}</div>`:''}</div>`}
async function sendVoiceSignal(targetId,signal){return api('voiceSignal',{roomId:session.roomId,playerToken:session.playerToken,targetId,signal})}
function voiceAudio(id){let a=document.querySelector(`#voice-${CSS.escape(id)}`);if(!a){a=document.createElement('audio');a.id=`voice-${id}`;a.autoplay=true;a.playsInline=true;a.dataset.voice='1';document.body.appendChild(a)}return a}
function closeVoicePeer(id){const pc=voice.peers.get(id);if(pc){try{pc.close()}catch{}voice.peers.delete(id)}voice.connected.delete(id);document.querySelector(`#voice-${CSS.escape(id)}`)?.remove()}
function createVoicePeer(targetId){if(voice.peers.has(targetId))return voice.peers.get(targetId);const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});voice.peers.set(targetId,pc);for(const track of voice.stream?.getTracks()||[])pc.addTrack(track,voice.stream);pc.onicecandidate=e=>{if(e.candidate)sendVoiceSignal(targetId,{type:'candidate',candidate:e.candidate.toJSON?.()||e.candidate}).catch(()=>{})};pc.ontrack=e=>{const a=voiceAudio(targetId);a.srcObject=e.streams[0];a.play().catch(()=>{})};pc.onconnectionstatechange=()=>{if(['connected'].includes(pc.connectionState))voice.connected.add(targetId);if(['failed','closed','disconnected'].includes(pc.connectionState))voice.connected.delete(targetId);render()};return pc}
async function offerVoice(targetId){const pc=createVoicePeer(targetId);if(pc.signalingState!=='stable')return;const offer=await pc.createOffer({offerToReceiveAudio:true});await pc.setLocalDescription(offer);await sendVoiceSignal(targetId,{type:'offer',sdp:pc.localDescription})}
async function handleVoiceSignal(payload){if(!voice.enabled||!payload?.from||!payload.signal)return;const {from,signal}=payload;if(signal.type==='leave'){closeVoicePeer(from);render();return}const pc=createVoicePeer(from);try{if(signal.type==='offer'){await pc.setRemoteDescription(signal.sdp);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await sendVoiceSignal(from,{type:'answer',sdp:pc.localDescription})}else if(signal.type==='answer'){if(pc.signalingState!=='stable')await pc.setRemoteDescription(signal.sdp)}else if(signal.type==='candidate'&&signal.candidate){await pc.addIceCandidate(signal.candidate)}}catch(e){console.warn('Voice signal error',e)}}
async function syncVoicePeers(){if(!voice.enabled||!session.state?.viewerId)return;const me=session.state.viewerId,others=session.state.players.filter(p=>p.id!==me&&p.connected).slice(0,7),allowed=new Set(others.map(p=>p.id));for(const id of [...voice.peers.keys()])if(!allowed.has(id))closeVoicePeer(id);for(const p of others){if(!voice.peers.has(p.id)&&String(me)<String(p.id))offerVoice(p.id).catch(()=>{})}}
async function startVoice(){voice.error=null;if(!voiceSupported())throw new Error('Voice chat is not supported by this browser.');if(!voiceIsSecure())throw new Error('Voice chat needs the hosted HTTPS version.');if((session.state?.players.length||0)>8)throw new Error('Voice chat supports up to 8 people.');voice.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});voice.enabled=true;voice.muted=false;await syncVoicePeers();render()}
function stopVoice(){if(session.state?.players)for(const p of session.state.players)if(p.id!==session.state.viewerId)sendVoiceSignal(p.id,{type:'leave'}).catch(()=>{});for(const id of [...voice.peers.keys()])closeVoicePeer(id);for(const track of voice.stream?.getTracks()||[])track.stop();voice.stream=null;voice.enabled=false;voice.muted=false;voice.connected.clear();document.querySelectorAll('audio[data-voice="1"]').forEach(a=>a.remove());render()}
function toggleVoiceMute(){voice.muted=!voice.muted;for(const t of voice.stream?.getAudioTracks()||[])t.enabled=!voice.muted;render()}

function lobbyTeamLabel(s,p){if(p.seat==null)return'';if(s.gameType===GAME.SMEAR)return `TEAM ${p.seat%2===0?'1':'2'}`;if(s.gameType===GAME.EUCHRE)return `TEAM ${p.seat%2===0?'1':'2'}`;if(s.gameType===GAME.TRAIL){if(s.settings.teamMode==='teams2')return `TEAM ${p.seat%2===0?'1':'2'}`;if(s.settings.teamMode==='teams3')return `TEAM ${['1','2','3'][p.seat%3]}`}if(s.gameType===GAME.MARBLES&&s.settings.teamMode==='teams')return `TEAM ${p.seat%2===0?'1':'2'}`;return''}
function lobbyTable(s){const ps=[...s.players].sort((a,b)=>(a.seat??99)-(b.seat??99)),pos=tablePositions(Math.max(ps.length,2)),mark=(gameMeta[s.gameType]?.name||s.gameName).toUpperCase().replaceAll(' ','\n');return `<div class="table-wrap"><div class="table players-${ps.length}"><div class="table-watermark compact-mark">${esc(mark)}</div>${ps.map((p,i)=>{const team=lobbyTeamLabel(s,p);return `<div class="seat occupied" style="left:${pos[i].left}%;top:${pos[i].top}%">${avatarHTML(p,'seat-avatar')}<div class="seat-name">${esc(p.name)}</div>${team?`<span class="team-badge">${team}</span>`:''}<span class="seat-state ${p.ready?'ready':''}">${p.ready?'READY':(p.seat==null?'NOT SEATED':`SEAT ${p.seat+1}`)}</span></div>`}).join('')}</div></div>`}
function clientMaxHand(s){if(s.gameType===GAME.SMEAR)return 6;const deck=s.gameType===GAME.FUCK?56:52;return Math.min(13,Math.floor(deck/Math.max(2,s.players.length)))}
function hostControls(s,me){if(me?.id!==s.hostPlayerId)return'';const others=s.players.filter(p=>p.id!==me.id);if(!others.length)return'';return `<div class="panel host-controls"><strong>Host controls</strong><div class="small muted">Remove someone who joined the wrong room or left before the game starts.</div><div class="host-player-list">${others.map(p=>`<div class="host-player-row">${avatarHTML(p,'score-avatar')}<span>${esc(p.name)}</span><button class="btn cream" data-remove-player="${p.id}">Remove</button></div>`).join('')}</div></div>`}
function option(v,label,current){return `<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(label)}</option>`}
function settingSelect(key,label,values,current){return `<div class="field"><label>${esc(label)}</label><select data-setting="${key}" class="setting-input">${values.map(x=>option(x[0],x[1],current)).join('')}</select></div>`}
function settingNumber(key,label,current,min=1,max=9999,step=1){return `<div class="field"><label>${esc(label)}</label><input data-setting="${key}" type="number" value="${Number(current)}" min="${min}" max="${max}" step="${step}"></div>`}
function extraSettingsPanel(s,isHost){const t=s.gameType,x=s.settings||{};let body='';
 if(t===GAME.FUCK)return `<div class="panel"><strong>Fuck Your Buddy setup</strong><p class="small muted">The host chooses how many random rounds the shuffled schedule will contain.</p>${isHost?`${settingNumber('roundCount','Rounds',x.roundCount||10,1,100)}<button class="btn gold full" data-action="saveSettings">Save setup</button>`:`<div class="game-info-plaque">${x.roundCount||10} random rounds</div>`}</div>`;
 if(t===GAME.SMEAR)return `<div class="panel smear-team-panel"><strong>Smear teams</strong><p class="small muted">Exactly four players. Seats 1 + 3 are Team 1; Seats 2 + 4 are Team 2.</p><div class="team-grid"><div class="team-card team-A"><strong>TEAM 1</strong><span>Seats 1 + 3</span></div><div class="team-card team-B"><strong>TEAM 2</strong><span>Seats 2 + 4</span></div></div></div>`;
 if(t===GAME.CAMPFIRE)body=`${settingSelect('mode','Game mode',[['quick','Quick Game'],['full','Full Campfire']],x.mode)}${x.mode==='full'?settingNumber('targetScore','Target score',x.targetScore||500,50,5000,50):''}`;
 if(t===GAME.TRAIL)body=settingSelect('teamMode','Play style',[['solo','Solo'],['teams2','Teams of 2'],['teams3','Teams of 3 (6 players)']],x.teamMode);
 if(t===GAME.PRAIRIE)body=`${settingNumber('startingChips','Starting chips',x.startingChips||100,10,10000,5)}${settingNumber('roundCount','Rounds',x.roundCount||10,1,50)}`;
 if(t===GAME.BURN_LOGS)body=settingNumber('targetLogs','Burn Logs to complete',x.targetLogs||7,3,12);
 if(t===GAME.DECK_SWEEP)body=settingNumber('roundCount','Rounds',x.roundCount||5,1,30);
 if(t===GAME.CRIBBAGE)body=settingSelect('countMode','Counting',[['auto','Auto Count'],['manual','Count It Myself']],x.countMode);
 if(t===GAME.MARBLES)body=settingSelect('teamMode','Play style',[['auto','Auto'],['solo','Solo'],['teams','Teams']],x.teamMode);
 if(t===GAME.GOLF)body=settingSelect('holes','Holes',[[6,'6 holes'],[9,'9 holes'],[18,'18 holes']],x.holes);
 if(t===GAME.POKER)body=`${settingSelect('mode','Poker mode',[['tournament','Tournament'],['cash','Cash Table']],x.mode)}${settingNumber('startingChips','Starting chips',x.startingChips||1000,100,100000,100)}<div class="setting-grid">${settingNumber('smallBlind','Small blind',x.smallBlind||10,1,10000)}${settingNumber('bigBlind','Big blind',x.bigBlind||20,2,20000)}</div><label class="setting-check"><input data-setting="blindIncrease" type="checkbox" ${x.blindIncrease?'checked':''}> Increase blinds automatically</label>`;
 if(t===GAME.PRESIDENT)body=settingNumber('roundCount','Rounds',x.roundCount||5,1,50);
 if(!body)return'';return `<div class="panel game-settings"><strong>${esc(s.gameName)} setup</strong><p class="small muted">${isHost?'Choose the game options before everyone readies up.':'Host-selected options are shown below.'}</p>${body}${isHost?`<button class="btn gold full" data-action="saveSettings" style="margin-top:12px">Save setup</button>`:''}</div>`}
function lobbyCountOK(s){const m=gameMeta[s.gameType]||{min:2,max:s.maxSeats},n=s.players.length;if(n<m.min||n>m.max)return false;if(s.gameType===GAME.TRAIL&&s.settings.teamMode==='teams2'&&![4,6].includes(n))return false;if(s.gameType===GAME.TRAIL&&s.settings.teamMode==='teams3'&&n!==6)return false;return true}
function lobbyInfo(s){const n=s.players.length,m=gameMeta[s.gameType]||{},bits=[`${n} player${n===1?'':'s'}`];if(s.gameType===GAME.SMEAR)bits.push('partners opposite','first to 11');else if(s.gameType===GAME.FUCK)bits.push(`max hand ${clientMaxHand(s)}`,'56-card Joker deck');else if(s.gameType===GAME.SCREW)bits.push(`max hand ${clientMaxHand(s)}`,'52-card deck');else if(s.gameType===GAME.EUCHRE)bits.push('partners opposite','play to 10');else if(s.gameType===GAME.POKER)bits.push(`${s.settings.mode==='cash'?'cash table':'tournament'}`,`${s.settings.startingChips} chips`);else if(s.gameType===GAME.LAST_HAVEN)bits.push('15 Survival Points','7-warning Raider cycle');else bits.push(m.sub||'');return bits.filter(Boolean).join(' · ')}
function lobby(){
 const s=session.state,me=s.players.find(p=>p.id===s.viewerId),isHost=me?.id===s.hostPlayerId,playerCountOK=lobbyCountOK(s),allReady=playerCountOK&&s.players.every(p=>p.ready&&p.seat!=null);
 const seatOptions=Array.from({length:s.maxSeats},(_,i)=>i).map(i=>{const fake={seat:i},team=lobbyTeamLabel(s,fake);return `<option value="${i}" ${me.seat===i?'selected':''} ${occupiedSeat(s,i,me.id)?'disabled':''}>Seat ${i+1}${team?` · ${team}`:''}${occupiedSeat(s,i,me.id)?' · taken':''}</option>`}).join('');
 const m=gameMeta[s.gameType]||{};const need=m.min===m.max?`Needs exactly ${m.min} players`:`${m.min}-${m.max} players`;
 return shell(`<main class="page"><div class="setup-head"><div><h1>${esc(s.gameName)}</h1><div class="small muted">${esc(lobbyInfo(s))}</div></div><div class="game-info-plaque">${esc(need)}</div></div><div style="height:14px"></div><div class="panel invite-panel"><div><strong>Invite your buddies</strong><div class="small muted invite-url">${esc(inviteLink())}</div></div><div class="row wrap invite-actions"><button class="btn primary" data-action="shareInvite">Share Invite</button><button class="btn cream" data-action="copy">Copy Link</button></div></div><div style="height:16px"></div><div class="lobby-layout"><div>${lobbyTable(s)}</div><aside class="sidebar"><div class="panel"><div class="spread"><strong>Your seat</strong><span class="small muted">Choose before Ready</span></div><select id="seatSelect" style="width:100%;margin-top:10px;border:1px solid #b99468;border-radius:10px;padding:11px;background:#fff7e8"><option value="">Choose a seat…</option>${seatOptions}</select>${lobbyTeamLabel(s,me)?`<div class="team-callout">You are on <strong>${esc(lobbyTeamLabel(s,me))}</strong></div>`:''}<div style="height:10px"></div><div class="field"><label>Name</label><input id="profileName" maxlength="24" value="${esc(me.name)}"></div><div style="height:10px"></div><button class="btn cream full" data-action="saveProfile">Save name</button></div>${extraSettingsPanel(s,isHost)}${voicePanel(s)}${hostControls(s,me)}<div class="panel"><div class="spread"><div><strong>Ready?</strong><div class="small muted">Everyone must choose a seat and press Ready.</div></div><button class="btn ${me.ready?'cream':'good'}" data-action="ready">${me.ready?'Unready':'Ready'}</button></div>${isHost?`<div style="height:12px"></div><button class="btn gold full" data-action="start" ${!allReady?'disabled':''}>Start ${esc(s.gameName)}</button>${!playerCountOK?`<div class="small muted" style="margin-top:8px;text-align:center">${esc(need)}${s.gameType===GAME.TRAIL?' for the selected team mode.':'.'}</div>`:''}`:''}</div></aside></div><div style="height:16px"></div>${avatarPicker(me)}</main>`)
}

function playerStatus(p,gameType){if(gameType===GAME.SMEAR)return'neutral';if(p.bid==null)return'neutral';if(p.tricks>p.bid)return'bad';if(p.tricks===p.bid)return'good';return'neutral'}
function trickPile(n){return `<div class="trick-pile">${Array.from({length:Math.min(n,9)},(_,i)=>`<span class="mini-back" style="left:${i*5}px;transform:rotate(${(i%2?1:-1)*(i*4)}deg)"></span>`).join('')}${n?`<span class="trick-count">${n}</span>`:''}</div>`}
function cardShort(c){if(c.joker)return c.joker==='high'?'HIGH JOKER':'LOW JOKER';return `${c.rank}${suitSymbol[c.suit]}`}
function cardHTML(c){if(c.joker)return `<div class="card joker-card ${c.joker}"><div>JOKER</div><div class="joker-star">${c.joker==='high'?'★':'☆'}</div><div>${c.joker==='high'?'HIGH':'LOW'}</div></div>`;const red=c.suit==='hearts'||c.suit==='diamonds';return `<div class="card ${red?'red':''}"><div>${c.rank}${suitSymbol[c.suit]}</div><div class="big">${suitSymbol[c.suit]}</div><div style="transform:rotate(180deg)">${c.rank}${suitSymbol[c.suit]}</div></div>`}
function firstNormalSuit(trick){return trick.find(x=>!x.card.joker)?.card.suit||null}
function sourceLabel(r){if(!r?.source?.length)return'';const normal=r.source.findLast? r.source.findLast(c=>!c.joker) : [...r.source].reverse().find(c=>!c.joker);if(r.source[0]?.joker)return `${r.source[0].joker==='high'?'High':'Low'} Joker + ${normal?cardShort(normal):'?'} → No Trump`;return cardShort(r.source[0])}
function schedulePanel(s,compact=false){if(s.gameType!==GAME.FUCK)return'';const g=s.game;return `<div class="panel schedule-panel ${compact?'compact':''}"><div class="spread"><strong>Tonight's rounds</strong><span class="small muted">${g.roundNumber}/${g.totalRounds}</span></div><div class="schedule-list">${g.schedule.map((r,i)=>`<div class="schedule-row ${i===g.roundIndex?'current':''} ${i<g.roundIndex?'done':''}"><span class="schedule-num">${i+1}</span><div><strong>${r.handSize} card${r.handSize===1?'':'s'} · ${suitSymbol[r.trump]} ${suitName[r.trump]}</strong><div class="tiny">Power: ${r.powerRank}s · ${esc(sourceLabel(r))}</div></div></div>`).join('')}</div></div>`}
function ceremonyOverlay(s){const c=s.game.dealerCeremony;if(!c)return'';const dealer=s.players.find(p=>p.id===c.dealerId);if(s.gameType===GAME.SMEAR||c.type==='random')return `<div class="phase-card" id="ceremony"><h2 style="margin-top:0">First dealer</h2>${dealer?avatarHTML(dealer,'seat-avatar'):''}<h3>${esc(dealer?.name||'Dealer')}</h3><p>The first dealer was chosen randomly. The deal moves clockwise after every hand.</p><button class="btn gold" data-action="dismissCeremony">Start Bidding</button></div>`;return `<div class="phase-card" id="ceremony"><h2 style="margin-top:0">Who deals first?</h2><p>Cards were dealt face-up clockwise until the first Jack appeared.</p><div class="ceremony-list">${c.sequence.slice(-10).map(x=>`<div class="ceremony-card ${!x.card.joker&&x.card.rank==='J'?'jack':''}"><div>${avatarHTML(s.players.find(p=>p.id===x.playerId),'ceremony-avatar')}</div><strong>${cardShort(x.card)}</strong></div>`).join('')}</div><h3>${esc(dealer?.name||'Dealer')} drew the first Jack!</h3><button class="btn gold" data-action="dismissCeremony">Deal Round 1</button></div>`}

function bidLabel(b){return b==='4out'?'4 & OUT':b==='pass'?'PASS':String(b??'–')}
function smearBidValueClient(b){return b==='4out'?5:b==='pass'||b==null?0:Number(b)||0}
function biddingOverlay(s,me){const g=s.game;if(g.phase!=='bidding')return'';const bidder=s.players.find(p=>p.id===g.bidTurnId);if(g.bidTurnId!==me.id)return `<div class="phase-card"><h2>Bidding</h2><p>Waiting for <strong>${esc(bidder?.name||'player')}</strong>…</p>${s.gameType===GAME.SMEAR&&g.highBid?`<div class="game-info-plaque">Current bid: ${bidLabel(g.highBid)}</div>`:''}</div>`;
 if(s.gameType===GAME.SMEAR){const opts=['pass','1','2','3','4','4out'],high=smearBidValueClient(g.highBid);return `<div class="phase-card smear-bid"><h2 style="margin-top:0">Bid for your team</h2><p class="muted small">Promise how many of High, Low, Jack and Game your team will earn. Each bid must beat the current bid.</p>${g.highBid?`<div class="game-info-plaque">Current bid: ${bidLabel(g.highBid)}</div>`:''}<div class="bid-grid">${opts.map(v=>{const disabled=v!=='pass'&&smearBidValueClient(v)<=high;return `<button class="bid ${session.selectedBid===v?'selected':''}" data-bid="${v}" ${disabled?'disabled':''}>${bidLabel(v)}</button>`}).join('')}</div><div class="small muted">4 & OUT means all four scoring points. Make it and your team wins the match; miss it and your team goes back 11.</div><div style="height:10px"></div><button class="btn primary full" data-action="confirmBid" ${session.selectedBid==null?'disabled':''}>Confirm ${session.selectedBid==null?'Bid':bidLabel(session.selectedBid)}</button></div>`}
 const bids=Array.from({length:g.handSize+1},(_,i)=>i);return `<div class="phase-card"><h2 style="margin-top:0">How many tricks?</h2><p class="muted small">Choose your bid, then confirm.</p><div class="bid-grid">${bids.map(n=>`<button class="bid ${session.selectedBid===n?'selected':''} ${g.forbiddenBid===n?'forbidden':''}" data-bid="${n}" ${g.forbiddenBid===n?'disabled':''}>${n}</button>`).join('')}</div>${g.forbiddenBid!=null?`<div class="small muted">Bid ${g.forbiddenBid} is unavailable because total bids cannot equal ${g.handSize}.</div>`:''}<div style="height:10px"></div><button class="btn primary full" data-action="confirmBid" ${session.selectedBid==null?'disabled':''}>Confirm Bid${session.selectedBid!=null?`: ${session.selectedBid}`:''}</button></div>`}

function roundDescription(s,r){if(s.gameType===GAME.SMEAR)return `6 cards · trump chosen by the winning bidder`;return `${r.handSize} card${r.handSize===1?'':'s'} · ${suitSymbol[r.trump]} ${suitName[r.trump]}${s.gameType===GAME.FUCK?` · Power ${r.powerRank}s`:''}`}
function awardLabel(team,pending=false){return team?`Team ${team==='A'?'1':'2'}`:(pending?'Pending':'No point')}
function resultsOverlay(s,me){const g=s.game;if(g.phase!=='roundResults')return'';if(s.gameType===GAME.SMEAR){const r=g.roundResults,bidder=s.players.find(p=>p.id===r.biddingPlayerId);return `<div class="phase-card smear-results" style="width:min(650px,92%)"><h2 style="margin-top:0">Hand ${g.roundNumber} complete</h2><div class="smear-contract ${r.made?'made':'set'}"><strong>${esc(bidder?.name||'Bidder')}</strong> bid <strong>${r.fourAndOut?'4 & OUT':r.contract}</strong> for Team ${r.biddingTeam==='A'?'1':'2'} · ${r.made?'MADE IT':'SET'}</div><div class="smear-awards"><div><span>HIGH</span><strong>${awardLabel(r.awards.high)}</strong></div><div><span>LOW</span><strong>${awardLabel(r.awards.low)}</strong></div><div><span>JACK</span><strong>${awardLabel(r.awards.jack)}</strong></div><div><span>GAME</span><strong>${awardLabel(r.awards.game)}</strong></div></div><div class="game-value-row">Game card value: Team 1 <strong>${r.gameValues.A}</strong> · Team 2 <strong>${r.gameValues.B}</strong>${r.awards.game==null?' · NO GAME OUT':''}</div><div class="team-scoreboard"><div class="team-card team-A"><span>TEAM 1</span><strong>${r.teamScores.A}</strong><small>+${r.points.A} scoring point${r.points.A===1?'':'s'} this hand</small></div><div class="team-card team-B"><span>TEAM 2</span><strong>${r.teamScores.B}</strong><small>+${r.points.B} scoring point${r.points.B===1?'':'s'} this hand</small></div></div><button class="btn ${me.continued?'cream':'good'} full" data-action="continue" ${me.continued?'disabled':''}>${me.continued?'Waiting for everyone…':'Continue to Next Hand'}</button></div>`}
 const next=g.schedule[g.roundIndex+1];return `<div class="phase-card" style="width:min(600px,90%)"><h2 style="margin-top:0">Round ${g.roundNumber} complete</h2><table class="score-table"><thead><tr><th>Player</th><th>Bid</th><th>Took</th><th>Points</th><th>Total</th></tr></thead><tbody>${g.roundResults.map(r=>{const p=s.players.find(x=>x.id===r.playerId),ok=r.bid===r.tricks;return `<tr><td>${avatarHTML(p,'score-avatar')}<span>${esc(p.name)}</span></td><td>${r.bid}</td><td class="${ok?'score-good':'score-bad'}">${r.tricks} ${ok?'✓':'×'}</td><td>+${r.points}</td><td>${r.total}</td></tr>`}).join('')}</tbody></table>${next?`<div class="next-round"><strong>Next:</strong> ${roundDescription(s,next)}</div>`:''}<button class="btn ${me.continued?'cream':'good'} full" data-action="continue" ${me.continued?'disabled':''}>${me.continued?'Waiting for everyone…':'Continue'}</button></div>`}

function gameOverOverlay(s){const g=s.game;if(g.phase!=='gameOver')return'';const winners=g.winnerIds.map(id=>s.players.find(p=>p.id===id)).filter(Boolean);if(s.gameType===GAME.SMEAR){const team=winners[0]?.team;return `<div class="phase-card"><div style="font-size:3rem">🏆</div><h2>Team ${team==='A'?'1':'2'} wins Smear!</h2><p class="muted">${winners.map(w=>esc(w.name)).join(' & ')}</p><div class="team-scoreboard"><div class="team-card team-A"><span>TEAM 1</span><strong>${g.teamScores.A}</strong></div><div class="team-card team-B"><span>TEAM 2</span><strong>${g.teamScores.B}</strong></div></div>${g.fourAndOut&&g.biddingTeam===team?`<div class="game-info-plaque">4 & OUT! Match won immediately.</div>`:''}<div style="height:12px"></div><button class="btn primary full" data-action="home">Return to Game Shelf</button></div>`}return `<div class="phase-card"><div style="font-size:3rem">🏆</div><h2>${winners.length>1?'Tie Game!':`${esc(winners[0]?.name||'Winner')} wins!`}</h2><p>${winners.map(w=>`${avatarHTML(w,'score-avatar')}<span>${esc(w.name)} · ${w.score} points</span>`).join('<br>')}</p><button class="btn primary full" data-action="home">Return to Game Shelf</button></div>`}

function ruleHint(s,g){if(g.phase!=='playing')return 'The app enforces bidding and card legality automatically.';const led=firstNormalSuit(g.currentTrick);if(s.gameType===GAME.SMEAR){if(!g.trump)return 'The winning bidder leads the first card. That card sets trump for this hand.';return led?`${suitSymbol[led]} ${suitName[led]} was led. Follow suit if able. ${suitSymbol[g.trump]} ${suitName[g.trump]} is trump.`:`${suitSymbol[g.trump]} ${suitName[g.trump]} is trump.`}if(s.gameType===GAME.FUCK){if(!led&&g.currentTrick.length)return 'A Joker was led. Jokers are always legal; the first normal card establishes the suit for players after it.';if(led)return `${suitSymbol[led]} ${suitName[led]} is the led suit. Follow it if able, but a Joker can be played anytime.`;return 'Lead any card. Jokers can be played at any time.'}return led?`${suitSymbol[led]} ${suitName[led]} was led. Follow suit if able.`:'Lead any card.'}

function smearHistoryLine(s,h){const bidder=s.players.find(p=>p.id===h.biddingPlayerId);return `<div class="small history-row"><strong>Hand ${h.roundIndex+1}</strong> · ${suitSymbol[h.trump]} ${suitName[h.trump]} · ${esc(bidder?.name||'Bidder')} bid ${h.fourAndOut?'4 & OUT':h.contract} ${h.made?'✓':'SET'}<br>High ${awardLabel(h.awards.high)} · Low ${awardLabel(h.awards.low)} · Jack ${awardLabel(h.awards.jack)} · Game ${awardLabel(h.awards.game)} · Score ${h.teamScores.A}-${h.teamScores.B}</div>`}
function gameplay(){
 const s=session.state,g=s.game,me=s.players.find(p=>p.id===s.viewerId),rotated=rotatePlayers(s.players,me.id),pos=tablePositions(rotated.length),posById=Object.fromEntries(rotated.map((p,i)=>[p.id,pos[i]])),round=g.schedule[g.roundIndex],turn=s.players.find(p=>p.id===g.turnPlayerId),canPlay=g.phase==='playing'&&g.turnPlayerId===me.id,selected=g.hand.find(c=>c.id===session.selectedCard),turnOffline=turn&&!turn.connected;
 const trick=`<div class="center-trick">${g.currentTrick.map(x=>{const pp=posById[x.playerId]||{left:50,top:50},left=50+(pp.left-50)*.44,top=50+(pp.top-50)*.40;return `<div class="played" style="left:${left}%;top:${top}%">${cardHTML(x.card)}</div>`}).join('')}</div>`;
 const hand=g.phase==='playing'?`<div class="hand">${g.hand.map(c=>{const legal=g.legalCardIds.includes(c.id);return `<button class="hand-card ${canPlay?(legal?'legal':'illegal'):''} ${session.selectedCard===c.id?'selected':''}" data-card="${c.id}" ${!canPlay||!legal?'disabled':''}>${cardHTML(c)}</button>`}).join('')}</div>`:'';
 const power=s.gameType===GAME.FUCK?` · POWER: ${round?.powerRank||'-'}s`:'';
 const smear=s.gameType===GAME.SMEAR,trumpText=smear?(g.trump?`${suitSymbol[g.trump]} ${suitName[g.trump]}`:'TRUMP NOT CHOSEN'): `${suitSymbol[g.trump]} ${suitName[g.trump]}`;
 const header=smear?`HAND ${g.roundNumber} · 6 CARDS · ${trumpText} · FIRST TO 11`:`ROUND ${g.roundNumber} OF ${g.totalRounds} · ${g.handSize} CARD${g.handSize===1?'':'S'} · ${trumpText}${power}`;
 const sub=smear?`DEALER: ${esc(s.players.find(p=>p.id===g.dealerId)?.name||'')}${g.contract?` · BID: ${g.fourAndOut?'4 & OUT':g.contract} BY ${esc(s.players.find(p=>p.id===g.highBidderId)?.name||'')}`:''} · TEAM 1 ${g.teamScores?.A??0} / TEAM 2 ${g.teamScores?.B??0}`:`DEALER: ${esc(s.players.find(p=>p.id===g.dealerId)?.name||'')}${s.gameType===GAME.FUCK?' · Random schedule':''}`;
 const history=g.history.length?g.history.slice().reverse().map(h=>smear?smearHistoryLine(s,h):`<div class="small history-row"><strong>Round ${h.roundIndex+1}</strong> · ${h.handSize} cards · ${suitSymbol[h.trump]} ${suitName[h.trump]}${s.gameType===GAME.FUCK?` · Power ${h.powerRank}s`:''}<br>${h.results.map(r=>{const p=s.players.find(x=>x.id===r.playerId);return `${esc(p?.name||'?')} ${r.bid}/${r.tricks} +${r.points}`}).join(' · ')}</div>`).join(''):`<div class="small muted">Completed ${smear?'hands':'rounds'} will appear here.</div>`;
 return shell(`<div class="roundbar">${header}<div class="sub">${sub}</div>${s.gameType===GAME.FUCK?`<button class="rounds-fab" data-action="toggleSchedule">Rounds</button>`:''}</div><main class="page"><div class="game-layout"><section class="game-table players-${rotated.length}">${turn?`<div class="turn-banner">${turn.id===me.id?'Your turn':`${esc(turn.name)}’s turn`}${turnOffline?' · reconnecting…':''}</div>`:''}${smear?`<div class="smear-score-float"><span>TEAM 1 <strong>${g.teamScores?.A??0}</strong></span><span>TEAM 2 <strong>${g.teamScores?.B??0}</strong></span></div>`:''}${rotated.map((p,i)=>`<div class="player-spot ${p.connected?'':'offline'} ${p.id===me.id?'me':''}" style="left:${pos[i].left}%;top:${pos[i].top}%"><div class="player-avatar-wrap">${avatarHTML(p,'avatar')}${p.id===g.dealerId?`<span class="dealer-chip">DEALER</span>`:''}</div><div class="player-name">${esc(p.name)}${p.id===me.id?' · YOU':''}</div>${smear?`<span class="team-badge team-${p.team}">TEAM ${p.team==='A'?'1':'2'}</span>`:''}<div class="stat-row"><span class="stat-pill ${playerStatus(p,s.gameType)}">Bid: ${p.bid==null?'–':bidLabel(p.bid)}</span><span class="stat-pill ${playerStatus(p,s.gameType)}">Tricks: ${p.tricks}</span><span class="stat-pill">${smear?'Team':'Score'}: ${p.score}</span></div>${trickPile(p.tricks)}</div>`).join('')}${trick}${hand}<button class="btn primary mobile-play-btn" data-action="confirmCard" ${!selected||!canPlay?'disabled':''}>${selected?`Play ${esc(cardShort(selected))}`:'Select a card'}</button>${(!session.ceremonyDismissed&&g.roundIndex===0)?ceremonyOverlay(s):''}${(!session.ceremonyDismissed&&g.roundIndex===0&&g.dealerCeremony)?'':biddingOverlay(s,me)}${resultsOverlay(s,me)}${gameOverOverlay(s)}${s.reaction?`<div class="floating-reaction">${esc(s.reaction.emoji)}</div>`:''}</section><aside class="sidebar">${schedulePanel(s)}${smear?`<div class="panel smear-live"><strong>Smear points</strong><div class="smear-awards mini"><div><span>HIGH</span><strong>${awardLabel(g.smearAwards?.high,true)}</strong></div><div><span>LOW</span><strong>${awardLabel(g.smearAwards?.low,true)}</strong></div><div><span>JACK</span><strong>${awardLabel(g.smearAwards?.jack,true)}</strong></div><div><span>GAME</span><strong>${awardLabel(g.smearAwards?.game,true)}</strong></div></div><p class="tiny">High & Low go to the teams that played them. Jack goes to the team that captures it. Game uses captured card values.</p></div>`:''}<div class="panel"><strong>Play</strong><p class="small muted">${ruleHint(s,g)}</p><button class="btn primary full" data-action="confirmCard" ${!selected||!canPlay?'disabled':''}>${selected?`Play ${esc(cardShort(selected))}`:'Select a card'}</button></div><div class="panel"><div class="spread"><strong>Quick reactions</strong><span class="small muted">live</span></div><div class="reactions" style="margin-top:8px">${['😂','😈','👏','🤦','🔥','👀'].map(e=>`<button class="reaction" data-react="${e}">${e}</button>`).join('')}</div></div><div class="panel"><div class="spread"><strong>Chat</strong><span class="small muted">${s.players.filter(p=>p.connected).length}/${s.players.length} online</span></div><div class="chat-box" id="chatBox">${s.chat.map(m=>`<div class="chat-msg"><strong>${esc(m.name)}:</strong> ${esc(m.text)}</div>`).join('')}</div><div class="row" style="margin-top:8px"><input id="chatInput" placeholder="Say something…" style="min-width:0;flex:1;border:1px solid #cbbfa9;border-radius:10px;padding:10px"><button class="btn cream" data-action="chat">Send</button></div></div><div class="panel"><strong>${smear?'Hand':'Round'} history</strong><div style="max-height:240px;overflow:auto;margin-top:8px">${history}</div></div>${voicePanel(s)}</aside></div>${session.scheduleOpen?`<div class="schedule-drawer"><button class="drawer-close" data-action="toggleSchedule">×</button>${schedulePanel(s,true)}</div>`:''}</main>`)
}

function extraCardLabel(c){if(!c)return'Hidden';if(c.kind){if(c.kind==='number')return `${c.rank} · ${String(c.color||'').toUpperCase()}`;return `${c.rank||c.kind}`;}if(c.joker||c.suit==='joker')return'JOKER';return `${c.rank||''}${suitSymbol[c.suit]||''}`}
function extraCardHTML(c,small=false){if(!c)return `<div class="card card-back ${small?'small-card':''}"><div class="big">🌲</div></div>`;if(c.kind){const map={fire:'#9e3f30',forest:'#2f6b4f',river:'#397ea5',lantern:'#c49334',wild:'#4c3c5f'},col=map[c.color]||map.wild;return `<div class="card camp-card ${small?'small-card':''}" style="--camp:${col}"><div>${esc(c.rank||c.kind)}</div><div class="big">${c.color==='fire'?'🔥':c.color==='forest'?'🌲':c.color==='river'?'💧':c.color==='lantern'?'🏮':'✦'}</div><div>${esc(String(c.color||'WILD').toUpperCase())}</div></div>`}if(c.joker||c.suit==='joker')return `<div class="card joker-card low ${small?'small-card':''}"><div>JOKER</div><div class="joker-star">★</div><div>${c.jokerIndex?`#${c.jokerIndex}`:''}</div></div>`;return cardHTML(c).replace('class="card ',`class="card ${small?'small-card ':''}`)}
function extraPlayerStat(s,e,p){const id=p.id,t=s.gameType;if(t===GAME.THIRTY_ONE)return `Lives ${p.score}${p.eliminated?' · OUT':''}`;if(t===GAME.CRAZY_EIGHTS)return `Level ${e.levels?.[id]??p.score}`;if(t===GAME.GOLF)return `Total ${p.score}`;if(t===GAME.POKER)return `Chips ${p.score}${p.eliminated?' · OUT':''}`;if(t===GAME.LAST_HAVEN)return `${e.points?.[id]??0}/15 SP · ${e.resourceCounts?.[id]??0} supplies`;if(t===GAME.EUCHRE){const tm=(p.seat%2===0?'A':'B');return `Team ${tm==='A'?1:2}: ${e.teamScores?.[tm]??0}`;}if(t===GAME.MITTS){const keys=Object.keys(e.teamScores||{}),k=keys.find(x=>String(x)===String(id))??(p.seat%2===0?'A':'B');return `Score ${p.score}`;}if(t===GAME.CRIBBAGE)return `${p.score}/121`;if(t===GAME.PRAIRIE)return `${p.score} chips`;if(t===GAME.BURN_LOGS)return `${e.completed?.[id]??0}/${e.target||7} logs`;if(t===GAME.DECK_SWEEP)return `${p.score} pts`;if(t===GAME.PRESIDENT)return `${p.score} rank pts`;if(t===GAME.CAMPFIRE)return e.mode==='full'?`${p.score} pts`:`${p.handCount} cards`;if(t===GAME.TRAIL){const q=e.pawns?.[id]||[],home=q.filter(x=>x.zone==='home').length;return `${home}/4 home`;}if(t===GAME.MARBLES){const q=e.pawns?.[id]||[],home=q.filter(x=>x.zone==='home').length;return `${home}/5 home`;}return `Score ${p.score}`}
function extraTurnId(e){return e.turnPlayerId||e.callTurnId||null}
function extraHandPanel(e){if(!Array.isArray(e.hand)||!e.hand.length)return'';return `<div class="extra-hand"><div class="small extra-hand-label">YOUR HAND · ${e.hand.length}</div><div class="extra-card-row">${e.hand.map(c=>extraCardHTML(c,true)).join('')}</div></div>`}
function golfBoard(s,e){const g=e.grids?.[s.viewerId]||[];return `<div class="golf-board"><div class="golf-title">YOUR 2 × 4 GRID</div><div class="golf-grid">${g.map(x=>x.face?extraCardHTML(x.card,true):extraCardHTML(null,true)).join('')}</div><div class="small muted">Current visible score: <strong>${e.yourScore??'?'}</strong></div></div>`}
function trailBoard(s,e,marbles=false){const rows=s.players.map(p=>{const q=e.pawns?.[p.id]||[];return `<div class="pawn-row"><span>${avatarHTML(p,'mini-avatar')}<strong>${esc(p.name)}</strong></span><div class="pawn-icons">${q.map(x=>`<i class="pawn-dot ${x.zone}" style="--pc:${p.color}" title="${x.zone}${x.dist!=null?` ${x.dist}`:''}"></i>`).join('')}</div><small>${q.filter(x=>x.zone==='home').length}/${q.length} home</small></div>`}).join('');return `<div class="race-board"><div class="race-sign">${marbles?'MARBLES & JOKERS':'TRAIL TROUBLE'}</div>${rows}${!marbles&&e.message?`<div class="board-message">${esc(e.message)}</div>`:''}</div>`}
function prairieBoard(e){return `<div class="prairie-board"><div class="prairie-center"><strong>PRAIRIE POT</strong><span>${e.pots?.prairie??0}</span></div><div class="pot-grid">${Object.entries(e.pots||{}).filter(([k])=>k!=='prairie').map(([k,v])=>`<div class="pot"><small>${esc(k.replaceAll('_',' ').toUpperCase())}</small><strong>${v}</strong></div>`).join('')}</div><div class="small">Poker: <strong>${esc(e.pokerName||'')}</strong></div></div>`}
function cribBoard(s,e){return `<div class="crib-board"><div class="crib-track">${s.players.map(p=>`<div class="crib-line"><span>${avatarHTML(p,'mini-avatar')} ${esc(p.name)}</span><div class="peg-track"><i style="width:${Math.min(100,(p.score/121)*100)}%;--pc:${p.color}"></i></div><strong>${p.score}</strong></div>`).join('')}</div><div class="crib-count"><span>Count <strong>${e.pegTotal||0}</strong></span>${e.starter?`<span>Starter ${extraCardLabel(e.starter)}</span>`:''}${e.lastCount?`<span>Last count +${e.lastCount.score}</span>`:''}</div></div>`}
function lastHavenBoard(s,e){const tiles=e.board?.tiles||[];if(!tiles.length)return'';const pts=tiles.map(t=>({t,x:(t.q+(t.r/2))*74,y:t.r*64})),minX=Math.min(...pts.map(z=>z.x)),maxX=Math.max(...pts.map(z=>z.x)),minY=Math.min(...pts.map(z=>z.y)),maxY=Math.max(...pts.map(z=>z.y)),w=maxX-minX+105,h=maxY-minY+95;const icons={timber:'🌲',scrap:'⚙',food:'🥫',fuel:'⛽',medicine:'✚',dead:'☠'};return `<div class="haven-wrap"><div class="haven-threat"><span>RAIDER WARNINGS</span><strong>${e.raiderWarnings||0}/7</strong><div>${Array.from({length:7},(_,i)=>`<i class="${i<(e.raiderWarnings||0)?'on':''}"></i>`).join('')}</div></div><div class="haven-board" style="width:${w}px;height:${h}px">${pts.map(({t,x,y})=>`<div class="hex resource-${t.resource}" style="left:${x-minX+18}px;top:${y-minY+10}px" title="${esc(t.resource)} ${t.number||''}"><b>${icons[t.resource]||'?'}</b><span>${t.number||''}</span>${e.raiderTile===t.id?'<em>☠</em>':''}</div>`).join('')}</div><div class="resource-rack">${Object.entries(e.resources||{}).map(([k,v])=>`<span><b>${icons[k]||''}</b>${esc(k)} <strong>${v}</strong></span>`).join('')}</div><div class="small muted">Trading Posts: ${(e.board?.tradingPosts||[]).map(p=>p.resource==='any'?'3:1':`${esc(p.resource)} 2:1`).join(' · ')||'none'}</div><div class="small muted">Longest Supply Line: ${esc(s.players.find(p=>p.id===e.longestOwner)?.name||'none')} · Strongest Patrol: ${esc(s.players.find(p=>p.id===e.patrolOwner)?.name||'none')}</div>${e.message?`<div class="board-message">${esc(e.message)}</div>`:''}</div>`}
function extraCenter(s,e){const t=s.gameType;
 if(t===GAME.CAMPFIRE)return `<div class="center-display"><h2>Campfire Chaos</h2><div class="feature-card">${extraCardHTML(e.topCard)}</div><div class="camp-color color-${e.currentColor}">${esc(String(e.currentColor||'').toUpperCase())}${e.pendingDraw?` · DRAW STACK ${e.pendingDraw}`:''}</div>${e.message?`<p>${esc(e.message)}</p>`:''}</div>`;
 if(t===GAME.THIRTY_ONE)return `<div class="center-display"><h2>31</h2><div class="feature-card">${extraCardHTML(e.topDiscard)}</div><div class="score-burst">Your suit score <strong>${e.yourScore}</strong></div>${e.knockerId?`<p>Knock called by ${esc(s.players.find(p=>p.id===e.knockerId)?.name||'player')}</p>`:''}</div>`;
 if(t===GAME.CRAZY_EIGHTS)return `<div class="center-display"><h2>Countdown ${e.yourLevel}</h2><div class="feature-card">${extraCardHTML(e.topCard)}</div><div class="score-burst">Your wild rank <strong>${esc(e.wildRank||'')}</strong> · Suit ${suitSymbol[e.currentSuit]||''}</div></div>`;
 if(t===GAME.PRESIDENT)return `<div class="center-display"><h2>Round ${e.round}/${e.roundCount}</h2><div class="pile-plate">${e.pile?`${e.pile.count} × <strong>${esc(e.pile.rank)}</strong>`:'Open pile'}</div><p>${e.out?.length?`${e.out.length} player${e.out.length===1?'':'s'} already out`:''}</p></div>`;
 if(t===GAME.GOLF)return golfBoard(s,e);
 if(t===GAME.EUCHRE)return `<div class="center-display"><h2>${e.trump?`${suitSymbol[e.trump]} ${suitName[e.trump]} TRUMP`:'CALLING TRUMP'}</h2><div class="feature-card">${extraCardHTML(e.upCard)}</div><div class="team-score-mini"><span>Team 1 <strong>${e.teamScores?.A??0}</strong></span><span>Team 2 <strong>${e.teamScores?.B??0}</strong></span></div><div class="trick-row">${(e.trick||[]).map(x=>extraCardHTML(x.card,true)).join('')}</div></div>`;
 if(t===GAME.CRIBBAGE)return cribBoard(s,e);
 if(t===GAME.TRAIL)return trailBoard(s,e,false);
 if(t===GAME.MARBLES)return trailBoard(s,e,true);
 if(t===GAME.PRAIRIE)return prairieBoard(e);
 if(t===GAME.BURN_LOGS)return `<div class="burn-board"><div class="burn-log"><small>YOUR BURN LOG</small><strong>${esc(e.mission?.name||'Mission')}</strong><span>${esc(e.mission?.text||e.mission?.name||'Complete your rummy mission')}</span></div><div class="meld-rack">${(e.melds||[]).map(m=>`<span>${esc(m.kind)} · ${m.count}</span>`).join('')}</div><div class="feature-card">${extraCardHTML(e.topDiscard)}</div></div>`;
 if(t===GAME.DECK_SWEEP)return `<div class="center-display"><h2>${e.message==='SWEEP!'?'🧹 SWEEP!':`Round ${e.round}/${e.roundCount}`}</h2><div class="feature-card">${extraCardHTML(e.topCard)}</div><div class="pile-plate">Center pile: ${(e.pile||[]).length} cards</div><div class="table-card-slots">${(e.layout?.[s.viewerId]?.up||[]).map(c=>c?extraCardHTML(c,true):'<span class="empty-slot"></span>').join('')}</div></div>`;
 if(t===GAME.MITTS)return `<div class="center-display"><h2>Mitts / Gloves / Socks</h2><div class="feature-card">${extraCardHTML((e.pile||[]).at(-1))}</div>${e.call?`<div class="call-plaque">${esc(e.call.kind.toUpperCase())} · ${esc(e.call.rank)} · ${e.call.remaining} left</div>`:''}<div class="pile-plate">Pile ${(e.pile||[]).length} cards · Deal ${e.dealNo}</div></div>`;
 if(t===GAME.POKER)return `<div class="poker-table-center"><div class="poker-pot">CURRENT BET <strong>${e.currentBet||0}</strong></div><div class="community-row">${[0,1,2,3,4].map(i=>e.community?.[i]?extraCardHTML(e.community[i]):'<span class="community-slot"></span>').join('')}</div><div class="small">Blinds ${e.smallBlind}/${e.bigBlind} · Hand ${e.handNo}</div>${e.lastResult?`<div class="board-message">${esc(e.lastResult.name||e.lastResult.awards?.[0]?.name||'Hand complete')}</div>`:''}</div>`;
 if(t===GAME.LAST_HAVEN)return lastHavenBoard(s,e);
 return `<div class="center-display"><h2>${esc(s.gameName)}</h2></div>`}
function actionCategory(a){const x=a.action||'';if(/Build|Route|Camp|Stronghold|Setup/.test(a.label)||/Build|Setup/.test(x))return'Build / Move';if(/Trade|Offer|Accept|Decline|Bank/.test(a.label)||/Trade|Offer/.test(x))return'Trade';if(/Draw|Take discard|Flip/.test(a.label)||/Draw/.test(x))return'Draw';if(/Play|Discard|Call|Bid|Fold|Check|Raise|Knock/.test(a.label))return'Play';return'Actions'}
function extraActionPanel(e){const actions=e.actions||[];if(!actions.length)return `<div class="panel action-panel"><strong>Actions</strong><p class="small muted">Waiting for another player or for the game to advance.</p></div>`;const groups={};actions.forEach((a,i)=>{const k=actionCategory(a);(groups[k]??=[]).push([a,i])});return `<div class="panel action-panel"><div class="spread"><strong>Your actions</strong><span class="small muted">${actions.length} available</span></div>${Object.entries(groups).map(([k,v],gi)=>`<details ${gi===0?'open':''}><summary>${esc(k)} <span>${v.length}</span></summary><div class="action-grid">${v.map(([a,i])=>`<button class="btn ${/LAST LOG|SWEEP|4 & OUT|All-In|SEND PACKING/.test(a.label)?'gold':'cream'}" data-extra-action="${i}">${esc(a.label)}</button>`).join('')}</div></details>`).join('')}</div>`}
function socialPanels(s){return `<div class="panel"><div class="spread"><strong>Quick reactions</strong><span class="small muted">live</span></div><div class="reactions" style="margin-top:8px">${['😂','😈','👏','🤦','🔥','👀'].map(e=>`<button class="reaction" data-react="${e}">${e}</button>`).join('')}</div></div><div class="panel"><div class="spread"><strong>Chat</strong><span class="small muted">${s.players.filter(p=>p.connected).length}/${s.players.length} online</span></div><div class="chat-box" id="chatBox">${s.chat.map(m=>`<div class="chat-msg"><strong>${esc(m.name)}:</strong> ${esc(m.text)}</div>`).join('')}</div><div class="row" style="margin-top:8px"><input id="chatInput" placeholder="Say something…" style="min-width:0;flex:1;border:1px solid #cbbfa9;border-radius:10px;padding:10px"><button class="btn cream" data-action="chat">Send</button></div></div>${voicePanel(s)}`}
function extraGameOver(s,e){if(s.game.phase!=='gameOver'&&e.phase!=='gameOver')return'';const winners=(s.game.winnerIds||[]).map(id=>s.players.find(p=>p.id===id)).filter(Boolean);return `<div class="phase-card extra-game-over"><div style="font-size:3rem">🏆</div><h2>${winners.length>1?'Winners!':`${esc(winners[0]?.name||'Winner')} wins!`}</h2><p>${winners.map(w=>`${esc(w.name)} · ${extraPlayerStat(s,e,w)}`).join('<br>')}</p><button class="btn primary full" data-action="home">Return to Game Shelf</button></div>`}
function extraGameplay(){const s=session.state,e=s.game.extra||{},me=s.players.find(p=>p.id===s.viewerId),rotated=rotatePlayers(s.players,me.id),pos=tablePositions(rotated.length),turnId=extraTurnId(e),turn=s.players.find(p=>p.id===turnId);const center=extraCenter(s,e),hand=extraHandPanel(e);return shell(`<div class="roundbar">${esc(s.gameName)}<div class="sub">${esc(String(e.phase||'').replaceAll('_',' ').toUpperCase())}${turn?` · ${turn.id===me.id?'YOUR TURN':`${turn.name}'S TURN`}`:''}</div></div><main class="page"><div class="game-layout"><section class="game-table extra-table extra-${s.gameType} players-${rotated.length}">${turn?`<div class="turn-banner">${turn.id===me.id?'Your turn':`${esc(turn.name)}’s turn`}${!turn.connected?' · reconnecting…':''}</div>`:''}${rotated.map((p,i)=>`<div class="player-spot ${p.connected?'':'offline'} ${p.id===me.id?'me':''}" style="left:${pos[i].left}%;top:${pos[i].top}%"><div class="player-avatar-wrap">${avatarHTML(p,'avatar')}${p.id===e.dealerId?`<span class="dealer-chip">DEALER</span>`:''}</div><div class="player-name">${esc(p.name)}${p.id===me.id?' · YOU':''}</div><div class="extra-stat">${esc(extraPlayerStat(s,e,p))}</div><div class="tiny light">${p.handCount} card${p.handCount===1?'':'s'}</div></div>`).join('')}<div class="extra-center">${center}</div>${hand}${extraGameOver(s,e)}${s.reaction?`<div class="floating-reaction">${esc(s.reaction.emoji)}</div>`:''}</section><aside class="sidebar">${extraActionPanel(e)}${socialPanels(s)}</aside></div></main>`)}

function render(){if(!session.roomId){app.innerHTML=home();bind();return}if(!session.playerToken){app.innerHTML=joinScreen();bind();return}if(!session.state){const waiting=session.connectionIssue?`<div class="panel connection-panel"><strong>Room connection is taking longer than expected.</strong><div class="small muted">Your game is still safe. Retry the room connection, or return to the game shelf and open a fresh invite.</div><div class="connection-actions"><button class="btn primary" data-action="retryConnect">Retry Connection</button><button class="btn cream" data-action="home">Back to Game Shelf</button></div></div>`:`<div class="panel connection-panel"><strong>Connecting to room…</strong><div class="small muted">Usually this only takes a moment.</div></div>`;app.innerHTML=shell(`<main class="page">${waiting}</main>`);bind();return}if(!session.state.viewerId){session.events?.close();session.events=null;session.playerToken=null;localStorage.removeItem(tokenKey('player'));session.state=null;loadPreview();app.innerHTML=joinScreen();bind();return}app.innerHTML=session.state.phase==='lobby'?lobby():(EXTRA_GAMES.has(session.state.gameType)?extraGameplay():gameplay());bind();requestAnimationFrame(()=>{const c=document.querySelector('#chatBox');if(c)c.scrollTop=c.scrollHeight})}
async function loadPreview(){if(!session.roomId)return;try{session.preview=await fetchState(session.roomId,'');render()}catch(e){setError(e)}}
function connect(){if(session.events)session.events.close();if(session.connectTimer)clearTimeout(session.connectTimer);if(!session.roomId||!session.playerToken)return;session.connectionIssue=false;const hydrate=async()=>{try{const s=await fetchState(session.roomId,session.playerToken);session.state=s;session.preview=s;session.connectionIssue=false;if(session.connectTimer)clearTimeout(session.connectTimer);render()}catch(e){if(!session.state){session.connectionIssue=true;render()}}};hydrate();session.connectTimer=setTimeout(()=>{if(!session.state){session.connectionIssue=true;render()}},8000);session.events=new EventSource(`/api/events?room=${encodeURIComponent(session.roomId)}&token=${encodeURIComponent(session.playerToken)}`);session.events.addEventListener('state',e=>{session.state=JSON.parse(e.data);session.preview=session.state;session.connectionIssue=false;if(session.connectTimer)clearTimeout(session.connectTimer);saveGameSummary(session.state);render();syncVoicePeers().catch(()=>{})});session.events.addEventListener('voice',e=>{try{handleVoiceSignal(JSON.parse(e.data))}catch{}});session.events.onerror=()=>{if(!session.state)hydrate()}}
async function createRoom(gameType){try{const name=session.name||'Host',d=await api('create',{name,gameType});session.roomId=d.roomId;session.playerToken=d.playerToken;session.hostToken=d.hostToken;session.state=null;session.connectionIssue=false;session.ceremonyDismissed=false;localStorage.setItem(tokenKey('player'),d.playerToken);localStorage.setItem(tokenKey('host'),d.hostToken);history.replaceState({},'',`/?room=${d.roomId}`);connect();render()}catch(e){setError(e)}}
async function joinRoom(){try{const name=document.querySelector('#joinName')?.value.trim()||'Player';session.name=name;localStorage.setItem('gn_name',name);const d=await api('join',{roomId:session.roomId,name});session.playerToken=d.playerToken;session.connectionIssue=false;localStorage.setItem(tokenKey('player'),d.playerToken);connect();render()}catch(e){setError(e)}}
function goHome(){if(voice.enabled)stopVoice();session.events?.close();session.events=null;if(session.connectTimer)clearTimeout(session.connectTimer);session.connectTimer=null;session.roomId=null;session.playerToken=null;session.hostToken=null;session.state=null;session.preview=null;session.selectedCard=null;session.selectedBid=null;session.connectionIssue=false;session.ceremonyDismissed=false;session.scheduleOpen=false;history.replaceState({},'','/');render()}

function bind(){
 document.querySelectorAll('[data-create-game]').forEach(el=>el.onclick=()=>createRoom(el.dataset.createGame));
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.action;try{
   if(a==='join')return joinRoom();if(a==='retryConnect'){session.connectionIssue=false;session.state=null;connect();render();return}if(a==='copy'){await navigator.clipboard.writeText(inviteLink());el.textContent='Copied!';setTimeout(render,900);return}if(a==='shareInvite'){const title=session.state?.gameName||'Black Family Game Night',url=inviteLink();if(navigator.share){await navigator.share({title,text:`Join my ${title} game`,url})}else{await navigator.clipboard.writeText(url);el.textContent='Link Copied!';setTimeout(render,900)}return}if(a==='home')return goHome();if(a==='toggleSchedule'){session.scheduleOpen=!session.scheduleOpen;render();return}if(a==='dismissCeremony'){session.ceremonyDismissed=true;render();return}if(a==='voiceToggle'){if(voice.enabled)stopVoice();else try{await startVoice()}catch(e){voice.error=e.message;render()}return}if(a==='voiceMute'){toggleVoiceMute();return}
   const b={roomId:session.roomId,playerToken:session.playerToken};
   if(a==='start')await api('start',{...b,hostToken:session.hostToken});
   if(a==='ready'){const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('ready',{...b,ready:!me.ready})}
   if(a==='saveProfile'){const me=session.state.players.find(p=>p.id===session.state.viewerId),name=document.querySelector('#profileName')?.value.trim()||me.name;session.name=name;localStorage.setItem('gn_name',name);await api('profile',{...b,name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:me.color})}
      if(a==='saveSettings'){const payload={...b,hostToken:session.hostToken};document.querySelectorAll('[data-setting]').forEach(el=>{payload[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value});await api('settings',payload)}
   if(a==='confirmBid'){if(session.selectedBid==null)return;await api('bid',{...b,bid:session.selectedBid});session.selectedBid=null}
   if(a==='confirmCard'){if(!session.selectedCard)return;await api('play',{...b,cardId:session.selectedCard});session.selectedCard=null}
   if(a==='continue')await api('continue',b);
   if(a==='chat'){const input=document.querySelector('#chatInput'),text=input?.value.trim();if(text){await api('chat',{...b,text});input.value=''}}
 }catch(e){setError(e)}});
 const seat=document.querySelector('#seatSelect');if(seat)seat.onchange=async()=>{if(seat.value==='')return;try{await api('seat',{roomId:session.roomId,playerToken:session.playerToken,seat:Number(seat.value)})}catch(e){setError(e)}};
 document.querySelectorAll('[data-avatar]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:el.dataset.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-color]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:el.dataset.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-style]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:me.avatar,variant:Number(el.dataset.style),outfitVariant:me.outfitVariant,color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-outfit]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:me.avatar,variant:me.variant,outfitVariant:Number(el.dataset.outfit),color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-remove-player]').forEach(el=>el.onclick=async()=>{try{await api('removePlayer',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,targetId:el.dataset.removePlayer})}catch(e){setError(e)}});
 document.querySelectorAll('[data-bid]').forEach(el=>el.onclick=()=>{session.selectedBid=session.state?.gameType===GAME.SMEAR?el.dataset.bid:Number(el.dataset.bid);render()});
 document.querySelectorAll('[data-card]').forEach(el=>el.onclick=()=>{session.selectedCard=el.dataset.card;render()});
 document.querySelectorAll('[data-extra-action]').forEach(el=>el.onclick=async()=>{try{const e=session.state?.game?.extra,a=e?.actions?.[Number(el.dataset.extraAction)];if(!a)return;await api('gameAction',{roomId:session.roomId,playerToken:session.playerToken,action:a.action,args:a.args||{}})}catch(err){setError(err)}});
 document.querySelectorAll('[data-react]').forEach(el=>el.onclick=()=>api('react',{roomId:session.roomId,playerToken:session.playerToken,emoji:el.dataset.react}).catch(setError));
 const chat=document.querySelector('#chatInput');if(chat)chat.onkeydown=e=>{if(e.key==='Enter')document.querySelector('[data-action="chat"]')?.click()}
}

if(session.roomId&&!session.playerToken)loadPreview();
render();if(session.roomId&&session.playerToken)connect();
